mapper.select:
select count(1) from biz_chain_deposit
where status = '0' and pay_amount = #{payAmount}
  and ifnull(nullif(network,''),'TRC20') = #{network}
  and lower(address) = lower(#{address}) and expire_time > sysdate()

select 
from biz_chain_deposit d
left join biz_member m on m.member_id = d.member_id
left join biz_member cm on cm.member_id = d.collect_member_id

    and d.member_id = #{memberId}
    and d.out_trade_no = #{outTradeNo}
    and d.status = #{status}
    and ifnull(nullif(d.network,''),'TRC20') = #{network}
    and d.tx_hash = #{txHash}
    and d.address = #{address}
    and d.address_source = #{addressSource}
    and d.collect_member_id = #{collectMemberId}
    and m.phone like concat('%', #{phone}, '%')
    and d.create_time >= #{params.beginTime}
    and d.create_time < date_add(#{params.endTime}, interval 1 day)

order by d.deposit_id desc

mapper.insert:
insert into biz_chain_deposit (
    out_trade_no, recharge_id, member_id, asset, network, currency, amount, pay_amount,
    address, address_source, collect_member_id, status, expire_time, create_time, remark
) values (
    #{outTradeNo}, #{rechargeId}, #{memberId}, #{asset}, #{network}, #{currency}, #{amount}, #{payAmount},
    #{address}, #{addressSource}, #{collectMemberId}, #{status}, #{expireTime}, sysdate(), #{remark}
)

mapper.update:
update biz_chain_deposit
recharge_id = #{rechargeId}, status = #{status}, tx_hash = #{txHash}, from_address = #{fromAddress}, paid_time = #{paidTime}, remark = #{remark}, update_time = sysdate()
where deposit_id = #{depositId}
